tape( 'the function computes row and column scale factors (column-major)', function test( t ) {
	var expectedOut;
	var expectedR;
	var expectedC;
	var data;
	var info;
	var out;
	var A;
	var R;
	var C;

	data = COLUMN_MAJOR;

	A = new Float64Array( data.A );
	R = new Float64Array( data.R );
	C = new Float64Array( data.C );
	out = new Float64Array( data.out );

	expectedR = new Float64Array( data.expected_R );
	expectedC = new Float64Array( data.expected_C );
	expectedOut = new Float64Array( data.expected_out );

	info = dgeequb( data.order, data.M, data.N, A, data.LDA, R, C, out );
	t.strictEqual( info, data.info, 'returns expected value' );
	t.deepEqual( R, expectedR, 'returns expected value' );
	t.deepEqual( C, expectedC, 'returns expected value' );
	t.deepEqual( out, expectedOut, 'returns expected value' );
	t.end();
});

