tape( 'the function sets `ROWCND` and `COLCND` to unity and `AMAX` to zero and returns `0` when `M` is zero', function test( t ) {
	var info;
	var out;
	var A;
	var R;
	var C;

	A = new Float64Array( 0 );
	R = new Float64Array( 0 );
	C = new Float64Array( 2 );
	out = new Float64Array( 3 );

	info = dgeequb( 'column-major', 0, 2, A, 1, R, C, out );
	t.strictEqual( info, 0, 'returns expected value' );
	t.deepEqual( out, new Float64Array( [ 1.0, 1.0, 0.0 ] ), 'returns expected value' );
	t.end();
});

